const body = $input.item.json.body || $input.item.json;

// Normalize domain
let rawDomain = (body.domain || '').trim().toLowerCase();
rawDomain = rawDomain.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];

if (!rawDomain && body.contact_email && body.contact_email.includes('@')) {
  rawDomain = body.contact_email.split('@')[1].toLowerCase();
}

const lead = {
  id: body.lead_id || 'LEAD-' + Date.now(),
  contact_name: (body.contact_name || 'Prospect').trim(),
  contact_email: (body.contact_email || '').trim().toLowerCase(),
  company_name: (body.company_name || 'Unknown Company').trim(),
  domain: rawDomain,
  notes: (body.notes || '').trim(),
  ingest_timestamp: new Date().toISOString()
};

return [{
  json: lead
}];

// Gathers domain intelligence
// In production, queries web APIs; runs deterministic heuristics for local offline testing
const lead = $input.item.json;
const domain = lead.domain;
const notes = lead.notes.toLowerCase();

let industry = 'Technology / Software';
let sizeTier = '50-250 employees';
let techStack = ['PostgreSQL', 'Docker', 'REST API', 'Node.js'];
let publicFunding = 'Series A / Profitable';

if (domain.includes('finscale') || notes.includes('financial') || notes.includes('reconciliation')) {
  industry = 'Financial Technology & Infrastructure';
  sizeTier = '100-500 employees';
  techStack = ['PostgreSQL', 'pgvector', 'Kafka', 'Kubernetes', 'n8n'];
  publicFunding = 'Series B ($35M)';
} else if (domain.includes('datadrive') || notes.includes('compliance')) {
  industry = 'Data Infrastructure & Compliance';
  sizeTier = '250-1000 employees';
  techStack = ['PostgreSQL', 'Multi-Cloud', 'Kubernetes', 'Terraform'];
  publicFunding = 'Growth Stage';
} else if (domain.includes('handyman') || domain.includes('local') || notes.includes('sms')) {
  industry = 'Local Trades & Services';
  sizeTier = '1-5 employees';
  techStack = ['WordPress', 'cPanel'];
  publicFunding = 'Bootstrapped';
}

return [{
  json: {
    ...lead,
    enrichment: {
      industry,
      size_tier: sizeTier,
      tech_stack: techStack,
      public_funding: publicFunding
    }
  }
}];

const lead = $input.item.json;
const enrichment = lead.enrichment;
const notes = lead.notes.toLowerCase();

// 4-Pillar ICP Scoring Rubric (Each 0 - 25 points, Total 0 - 100)
let industryScore = 10;
let sizeScore = 10;
let techScore = 10;
let painPointScore = 10;

// 1. Industry Fit (Target: B2B SaaS, FinTech, Data Infrastructure)
if (enrichment.industry.includes('Financial') || enrichment.industry.includes('Compliance')) {
  industryScore = 25;
} else if (enrichment.industry.includes('Technology')) {
  industryScore = 20;
} else {
  industryScore = 5;
}

// 2. Company Size Fit (Target: 50 - 1000 employees)
if (enrichment.size_tier.includes('250-1000')) {
  sizeScore = 25;
} else if (enrichment.size_tier.includes('100-500') || enrichment.size_tier.includes('50-250')) {
  sizeScore = 22;
} else {
  sizeScore = 5;
}

// 3. Tech Stack Fit (Target: Modern backend, PostgreSQL, orchestration)
const matchedTech = enrichment.tech_stack.filter(t => ['PostgreSQL', 'Kubernetes', 'Kafka', 'pgvector', 'n8n'].includes(t));
techScore = Math.min(25, 10 + matchedTech.length * 4);

// 4. Pain Point & Buying Signal Fit
if (notes.includes('reconciliation') || notes.includes('compliance') || notes.includes('multi-cloud') || notes.includes('ledger') || notes.includes('orchestration')) {
  painPointScore = 24;
} else if (notes.includes('automation') || notes.includes('pipeline') || notes.includes('financial')) {
  painPointScore = 18;
} else {
  painPointScore = 6;
}

const totalIcpScore = industryScore + sizeScore + techScore + painPointScore;

let icpTier = 'Tier 3 - Disqualified';
let rationale = '';

if (totalIcpScore >= 80) {
  icpTier = 'Tier 1 - High Priority';
  rationale = `High-fit ${enrichment.industry} enterprise with ${enrichment.size_tier} and active operational demand for automated workflow validation.`;
} else if (totalIcpScore >= 60) {
  icpTier = 'Tier 2 - Nurture';
  rationale = `Moderate fit with relevant tech stack (${enrichment.tech_stack.join(', ')}), but smaller team footprint or less acute operational signals.`;
} else {
  icpTier = 'Tier 3 - Disqualified';
  rationale = `Non-target profile. Minimal alignment with enterprise automation and low engineering integration requirements.`;
}

return [{
  json: {
    ...lead,
    icp_score: totalIcpScore,
    icp_tier: icpTier,
    score_breakdown: {
      industry_fit: industryScore,
      company_size_fit: sizeScore,
      tech_stack_fit: techScore,
      pain_point_fit: painPointScore
    },
    qualification_rationale: rationale,
    is_qualified: totalIcpScore >= 60
  }
}];

const lead = $input.item.json;
const firstName = lead.contact_name.split(' ')[0] || 'there';
const company = lead.company_name;

// Generate 3 contextual subject lines
const subjectLines = [
  `Automating multi-cloud compliance trails for ${company}`,
  `Question regarding ${company} audit workflows`,
  `Reconciliation architecture for your data squad`
];

// Humanized 3-paragraph outreach email following humanizer rules (factual, no buzzwords)
const emailBody = `Hi ${firstName},nnI reviewed ${company}'s infrastructure profile and noticed your focus on ${lead.enrichment.industry.toLowerCase()}. Engineering teams operating at this scale often find that connecting disparate database records to internal compliance checkpoints creates recurring manual overhead.nnWe built an automated workflow blueprint in n8n that pairs database cross-checks with human approval steps in Slack, verifying transactional records before downstream execution.nnWould you be open to a 10-minute technical exchange next Tuesday to see how other ${company} peers structure these reconciliation checks?nnBest regards,nAlexandr Motologa`;

return [{
  json: {
    ...lead,
    email_draft: {
      subject_lines: subjectLines,
      selected_subject: subjectLines[0],
      body: emailBody
    }
  }
}];

const lead = $input.item.json;

const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: `🎯 New Qualified Lead: ${lead.company_name} (Score: ${lead.icp_score}/100)`,
      emoji: true
    }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Contact:* ${lead.contact_name} (<mailto:${lead.contact_email}|${lead.contact_email}>)` },
      { type: 'mrkdwn', text: `*Domain:* `${lead.domain}`` },
      { type: 'mrkdwn', text: `*ICP Tier:* *${lead.icp_tier}*` },
      { type: 'mrkdwn', text: `*Industry:* ${lead.enrichment.industry}` },
      { type: 'mrkdwn', text: `*Size:* ${lead.enrichment.size_tier}` },
      { type: 'mrkdwn', text: `*Tech Stack:* `${lead.enrichment.tech_stack.slice(0, 3).join(', ')}`` }
    ]
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Qualification Rationale:*n${lead.qualification_rationale}`
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Outreach Draft Preview (${lead.email_draft.selected_subject}):*n```n${lead.email_draft.body.slice(0, 350)}...n````
    }
  },
  {
    type: 'actions',
    block_id: 'lead_actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Approve & Send Email' },
        style: 'primary',
        action_id: 'action_approve_outreach',
        value: JSON.stringify({ lead_id: lead.id, action: 'send_outreach' })
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Edit in HubSpot' },
        action_id: 'action_open_hubspot',
        url: `https://app.hubspot.com/contacts/leads/${lead.id}`
      }
    ]
  }
];

return [{
  json: {
    ...lead,
    slack_payload: { blocks }
  }
}];
